{"output":"const DEFAULT_TIMEOUT_MS = 120000; // 2 minutes

const getBaseUrl = () => {
  const app = getApp();
  return app?.globalData?.apiBaseUrl || '';
};

const request = (options) => {
  const baseUrl = getBaseUrl();
  const {
    url,
    method = 'GET',
    data,
    header,
    acceptNotModified = false,
    timeout = DEFAULT_TIMEOUT_MS
  } = options;
  return new Promise((resolve, reject) => {
    wx.request({
      url: `${baseUrl}${url}`,
      method,
      data,
      header,
      timeout,
      success: (res) => {
        if (res.statusCode === 304 && acceptNotModified) {
          resolve({ notModified: true });
          return;
        }

        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve(res.data);
        } else {
          reject(new Error(`Request failed: ${res.statusCode}`));
        }
      },
      fail: reject
    });
  });
};

export const api = {
  listThemes(params = {}, options = {}) {
    const queryString = Object.entries(params)
      .filter(([, value]) => value !== undefined && value !== null && value !== '')
      .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(String(value))}`)
      .join('&');
    const url = queryString ? `/themes?${queryString}` : '/themes';
    return request({ url, acceptNotModified: options.acceptNotModified });
  },

  startStory({ themeId, modelProvider }) {
    const payload = { themeId };
    if (modelProvider) {
      payload.modelProvider = modelProvider;
    }
    return request({
      url: '/stories',
      method: 'POST',
      data: payload,
      timeout: DEFAULT_TIMEOUT_MS
    });
  },

  advanceStory({ sessionId, selectedOption, modelProvider }) {
    const payload = { selectedOption };
    if (modelProvider) {
      payload.modelProvider = modelProvider;
    }
    return request({
      url: `/stories/${sessionId}/turns`,
      method: 'POST',
      data: payload,
      timeout: DEFAULT_TIMEOUT_MS
    });
  }
};
